sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading) return;

  if (!newValue) return;

  g_form.hideFieldMsg('user', true);

  var ga = new GlideAjax('x_1834930_office_0.BaseRegistrationGuard');
  ga.addParam('sysparm_name', 'hasUserActiveRegistration');
  ga.addParam('sysparm_user_id', newValue);
  ga.addParam('sysparm_exclude_id', g_form.getUniqueValue() || '');

  ga.getXMLAnswer(function(answer) {
    var res = {};
    try { res = JSON.parse(answer || '{}'); } catch (e) {
      var err = 'Could not validate user registration. Please try again.';
      g_form.addErrorMessage(err);
      alert(err);
      return;
    }

    if (res.ok === false) {
      var msg = 'This user already has a pending/approved registration.';

      g_form.addErrorMessage(msg);
      g_form.showFieldMsg('user', msg, 'error');
      alert(msg);

      g_form.setValue('user', '');
    }
  });
}
